package org.example.behavioral_pattern.strategy_pattern.delivery.impl;import org.example.behavioral_pattern.strategy_pattern.delivery.Order;import org.example.behavioral_pattern.strategy_pattern.delivery.ShippingStrategy;public class SameDayShippingStrategy implements ShippingStrategy {    @Override    public int calculateFee(Order order) {        int baseFee = 100;        if (order.getWeightInGram() > 1000) {            baseFee += 20;        }        return baseFee;    }}